import com.oracle.e1.common.OrchestrationAttributes;
import java.text.SimpleDateFormat;
import groovy.json.*;

HashMap<String, Object> main(OrchestrationAttributes orchAttr, HashMap inputMap)
{
HashMap<String, Object> returnMap = new HashMap<String, Object>();


BigDecimal UpdateBUCheck = null;
String UpdateBUCheck_str = (String)inputMap.get("UpdateBUCheck");
if(UpdateBUCheck_str != null && !UpdateBUCheck_str.trim().isEmpty())
{
UpdateBUCheck = new BigDecimal(UpdateBUCheck_str);
}    

String UpdateOrderNumber = (String)inputMap.get("UpdateOrderNumber");

String Status = "UNKNOWN";
String Action = "UNKNOWN";
String Errors = "";

if(UpdateBUCheck == 0) //BU check did NOT Pass
{
Action = "ERROR";
Status = "FAILURE";
Errors = Errors + "Supplied Business Unit Does Not Exist or Is Not Available For Posting\n";           
}

if(UpdateOrderNumber!=null && !UpdateOrderNumber.trim().isEmpty()) //A value is only returned if the update ran successfully
{
Action = "UPDATE";
Status = "SUCCESS";
}
else //If NO value was returned then the Update did not run
{
if(Status != "FAILURE") //Assume it was a status issue, because if it is was true error then this code would not be executed.
{
Action = "ERROR";
Status = "FAILURE";
Errors = Errors + "Supplied Status is not valid or Is Not Valid to Transition to\n";           
}
}

returnMap.put("Action", Action);        
returnMap.put("Status", Status);   
returnMap.put("Errors", Errors);   

return returnMap;
}
